package pdfgen

import (
	"fmt"
	"io"
	"os"
	"strings"
	"sync"
	"time"
	"unicode"
)

// AuditLogger handles structured logging for PDF generation events
type AuditLogger struct {
	mu     sync.Mutex
	writer io.Writer
	prefix string
}

// NewAuditLogger creates a logger writing to the specified file
func NewAuditLogger(logPath string) (*AuditLogger, error) {
	f, err := os.OpenFile(logPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0600)
	if err != nil {
		return nil, err
	}
	return &AuditLogger{writer: f, prefix: "pdfgen"}, nil
}

// sanitizeField removes control characters that could corrupt log structure
func (al *AuditLogger) sanitizeField(input string) string {
	var builder strings.Builder
	builder.Grow(len(input))
	for _, r := range input {
		if unicode.IsControl(r) {
			builder.WriteRune('\uFFFD')
		} else {
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

// normalizeUnicode applies NFKC-like normalization for consistent logging
func (al *AuditLogger) normalizeUnicode(input string) string {
	// Replace common Unicode confusables with ASCII equivalents
	replacements := map[rune]rune{
		'\u2028': ' ',  // Line Separator -> space
		'\u2029': ' ',  // Paragraph Separator -> space
		'\u0085': ' ',  // Next Line -> space
		'\u000B': ' ',  // Vertical Tab -> space
		'\u000C': ' ',  // Form Feed -> space
		'\ufeff': '\x00', // BOM -> null (filtered later)
	}
	var builder strings.Builder
	builder.Grow(len(input))
	for _, r := range input {
		if rep, ok := replacements[r]; ok {
			if rep != '\x00' {
				builder.WriteRune(rep)
			}
		} else {
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

// LogEvent writes a structured audit log entry
func (al *AuditLogger) LogEvent(eventType, documentTitle, username string, metadata map[string]string) {
	al.mu.Lock()
	defer al.mu.Unlock()

	timestamp := time.Now().UTC().Format(time.RFC3339)

	// First normalize unicode, then sanitize control chars
	safeTitle := al.sanitizeField(al.normalizeUnicode(documentTitle))
	safeUser := al.sanitizeField(al.normalizeUnicode(username))

	// Build metadata string
	var metaParts []string
	for k, v := range metadata {
		cleanKey := al.sanitizeField(al.normalizeUnicode(k))
		cleanVal := al.sanitizeField(al.normalizeUnicode(v))
		metaParts = append(metaParts, fmt.Sprintf("%s=%s", cleanKey, cleanVal))
	}
	metaStr := strings.Join(metaParts, "; ")

	logLine := fmt.Sprintf("[%s] %s | event=%s | doc=\"%s\" | user=\"%s\" | meta={%s}\n",
		timestamp, al.prefix, eventType, safeTitle, safeUser, metaStr)

	fmt.Fprint(al.writer, logLine)
}

// PDFDocument represents a document being generated
type PDFDocument struct {
	Title    string
	Author   string
	Pages    []PDFPage
	logger   *AuditLogger
}

// PDFPage represents a single page
type PDFPage struct {
	Content  string
	PageNum  int
}

// escapePDFString escapes a string so it can be safely embedded inside a
// PDF string literal delimited by parentheses. This prevents PDF content
// injection where a ')' or backslash could break out of the string object.
func escapePDFString(input string) string {
	var builder strings.Builder
	builder.Grow(len(input) + 8)
	for _, r := range input {
		switch r {
		case '\\':
			builder.WriteString("\\\\")
		case '(':
			builder.WriteString("\\(")
		case ')':
			builder.WriteString("\\)")
		case '\n':
			builder.WriteString("\\n")
		case '\r':
			builder.WriteString("\\r")
		case '\t':
			builder.WriteString("\\t")
		case '\b':
			builder.WriteString("\\b")
		case '\f':
			builder.WriteString("\\f")
		default:
			if unicode.IsControl(r) {
				// Drop other control characters entirely.
				continue
			}
			builder.WriteRune(r)
		}
	}
	return builder.String()
}

// NewPDFDocument creates a new document with audit logging
func NewPDFDocument(title, author string, logger *AuditLogger) *PDFDocument {
	doc := &PDFDocument{
		Title:  title,
		Author: author,
		logger: logger,
	}
	logger.LogEvent("doc_created", title, author, nil)
	return doc
}

// AddPage adds content to the document
func (doc *PDFDocument) AddPage(content string) {
	pageNum := len(doc.Pages) + 1
	doc.Pages = append(doc.Pages, PDFPage{Content: content, PageNum: pageNum})
	doc.logger.LogEvent("page_added", doc.Title, doc.Author,
		map[string]string{"page": fmt.Sprintf("%d", pageNum)})
}

// Render generates the PDF output
func (doc *PDFDocument) Render(w io.Writer) error {
	// Simplified PDF rendering. Title and Author are escaped to prevent
	// breaking out of the PDF string literal (PDF content injection).
	header := fmt.Sprintf("%%PDF-1.4\n1 0 obj\n<< /Title (%s) /Author (%s) >>\nendobj\n",
		escapePDFString(doc.Title), escapePDFString(doc.Author))
	_, err := w.Write([]byte(header))
	if err != nil {
		return err
	}

	for _, page := range doc.Pages {
		pageData := fmt.Sprintf("stream\n%s\nendstream\n", page.Content)
		_, err = w.Write([]byte(pageData))
		if err != nil {
			return err
		}
	}

	doc.logger.LogEvent("doc_rendered", doc.Title, doc.Author,
		map[string]string{"pages": fmt.Sprintf("%d", len(doc.Pages))})
	return nil
}
